<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { auth, db } from './firebase'
import { createUserWithEmailAndPassword, onAuthStateChanged, signInWithEmailAndPassword, signOut, updateProfile } from 'firebase/auth'
import { addDoc, collection, deleteDoc, doc, getDocs, onSnapshot, runTransaction, serverTimestamp, setDoc, Timestamp, updateDoc, writeBatch } from 'firebase/firestore'
import TicketAlbum from './TicketAlbum.vue'

const iconFiles = [...Array.from({length:23},(_,i)=>String(i+1).padStart(2,'0')+'.webp'),'24.jpg']
const assetUrl = path => import.meta.env.BASE_URL + path.replace(/^\//,'')
const cloudCatImage = assetUrl('images/cloud-cat.png')
const pickedIcons = [...iconFiles].sort(()=>Math.random()-.5).slice(0,7).map(file=>assetUrl('icons/'+encodeURIComponent(file)))
const sidebarIcon = assetUrl('icons/side-cinnamoroll.png')
const homepageIcon = assetUrl('icons/homepage-cinnamoroll.jpg')
const holidaySeeds = [{month:1,day:1,name:'元旦',emoji:'🎆',about:'迎接新的一年。'},{month:2,day:14,name:'情人節',emoji:'💝',about:'用小小心意表達愛意。'},{month:3,day:14,name:'白色情人節',emoji:'🍬',about:'在情人節之後回應心意的日子。'},{month:5,day:20,name:'520 我愛你日',emoji:'💕',about:'以「520」諧音傳達我愛你。'},{month:12,day:24,name:'平安夜',emoji:'🕯️',about:'聖誕節前夕，常與親友相聚。'},{month:12,day:25,name:'聖誕節',emoji:'🎄',about:'世界各地分享祝福與節慶氣氛的日子。'},{month:12,day:31,name:'跨年夜',emoji:'🎇',about:'一起倒數，迎接新年。'}]
const tabs = ['首頁','任務','獎品','兌換','票根','紀錄','設定'].map((label,i)=>[pickedIcons[i],label])
const backgroundImage = assetUrl('backgrounds/762886.jpg')
const page = ref('首頁'), section = ref('今日任務'), prizeSection = ref('獎品'), show = ref(''), user = ref(null), profile = ref(null), partner = ref(null)
const coupleDates = ref({togetherDate:'',myBirthday:'',partnerBirthday:''})
const savedCoupleDateData = ref({}), otherUserId = ref('')
const starterRewards = [{id:'starter-movie',title:'指定一部電影之夜',points:35,emoji:'🎬'},{id:'starter-breakfast',title:'早餐由我來準備',points:25,emoji:'🥞'},{id:'starter-hug',title:'一個大大的擁抱',points:15,emoji:'🫂'}]
const tasks = ref([]), rewards = ref([...starterRewards]), redemptions = ref([])
const name = computed(()=>profile.value?.name || user.value?.displayName || '貓咪旅人')
const availablePoints = uid => {const account=uid===user.value?.uid?profile.value:partner.value,earned=tasks.value.filter(t=>t.status==='done'&&t.receiverId===uid&&!t.pointsCredited).reduce((n,t)=>n+Number(t.roll??t.points??0),0),reserved=redemptions.value.filter(r=>r.requesterId===uid&&(r.status==='pending'||(r.status==='approved'&&!r.pointsDebited))).reduce((n,r)=>n+Number(r.points||0),0);return Math.max(0,Number(account?.pointsBalance||0)+earned-reserved)}
const points = computed(()=>user.value?availablePoints(user.value.uid):0)
const partnerPoints = computed(()=>partner.value?availablePoints(partner.value.id):0)
const reservedPoints = computed(()=>redemptions.value.filter(r=>r.requesterId===user.value?.uid&&r.status==='pending').reduce((sum,r)=>sum+Number(r.points||0),0))
const groupOwnedPrizes = uid => {const owned=redemptions.value.filter(r=>r.requesterId===uid&&r.status==='approved'),groups=new Map();for(const prize of owned){const group=groups.get(prize.title)||{...prize,id:prize.title,quantity:0,prizeIds:[]};group.quantity++;group.prizeIds.push(prize.id);groups.set(prize.title,group)}return [...groups.values()]}
const myPrizes = computed(()=>groupOwnedPrizes(user.value?.uid))
const partnerPrizes = computed(()=>groupOwnedPrizes(partner.value?.id))
const usedPrizes = computed(()=>redemptions.value.filter(r=>r.requesterId===user.value?.uid&&r.status==='used'))
const pendingPrizes = computed(()=>redemptions.value.filter(r=>(r.approverId===user.value?.uid||r.requesterId===user.value?.uid)&&['pending','use_pending'].includes(r.status)))
const prizesToReview = computed(()=>pendingPrizes.value.filter(r=>r.approverId===user.value?.uid))
const taskNeedsAttention = t => (t.receiverId===user.value?.uid&&['open','rejected'].includes(t.status)&&!expired(t))||(t.creatorId===user.value?.uid&&t.status==='review')
const hasTaskAttention = computed(()=>{clock.value;return tasks.value.some(taskNeedsAttention)})
const hasPrizeAttention = computed(()=>prizesToReview.value.length>0)
const redemptionsToReview = computed(()=>redemptions.value.filter(r=>r.approverId===user.value?.uid&&r.status==='pending'))
const myRedemptions = computed(()=>redemptions.value.filter(r=>r.requesterId===user.value?.uid).sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0)))
const historyRecords = computed(()=>{const uid=user.value?.uid;if(!uid)return[];const taskRecords=tasks.value.filter(t=>['done','review','rejected'].includes(t.status)&&(t.creatorId===uid||t.receiverId===uid)).map(t=>{const points=Number(t.roll??t.points??0),when=t.reviewedAt||t.completedAt||t.rejectedAt||t.createdAt;let detail,amount='';if(t.status==='review'){detail=t.receiverId===uid?'你已完成任務，等待發布者驗收。':'對方已完成任務，等待你驗收。';amount=t.receiverId===uid?`待 ${points} 點`:'待驗收'}else if(t.status==='done'){detail=t.receiverId===uid?'任務已驗收，點數已入帳。':'你已驗收對方的任務。';amount=t.receiverId===uid?`+ ${points} 點`:'已驗收'}else{detail=t.rejectReason?`任務遭駁回：${t.rejectReason}`:'任務已遭駁回。';amount='已退回'}return{id:'task-'+t.id,icon:'📝',title:t.title,detail,amount,status:t.status,statusLabel:t.status==='review'?'等待驗收':t.status==='done'?'已完成':'已駁回',when,kind:'task'}});const redemptionRecords=redemptions.value.filter(r=>r.requesterId===uid||r.approverId===uid).map(r=>{const requester=r.requesterId===uid,detail=r.status==='pending'?(requester?'等待另一半確認兌換，點數暫時保留。':'另一半申請兌換，等待你確認。'):r.status==='rejected'?(requester?'兌換遭拒，保留的點數已釋放。':'你已拒絕兌換。'):r.status==='use_pending'?(requester?'等待另一半確認使用獎品。':'另一半申請使用獎品，等待你確認。'):r.status==='used'?'獎品已確認使用。':requester?'兌換已確認，獎品在獎品區。':'你已確認兌換。',amount=r.status==='pending'&&requester?`待 ${r.points} 點`:r.status==='rejected'&&requester?`+ ${r.points} 點`:['approved','use_pending','used'].includes(r.status)&&requester?`− ${r.points} 點`:'',rStatus=r.status;return{id:'redeem-'+r.id,icon:r.emoji||'🎁',title:r.title,detail,amount,status:rStatus,statusLabel:rStatus==='pending'?'等待兌換確認':rStatus==='use_pending'?'等待使用確認':rStatus==='used'?'已兌換':rStatus==='approved'?'已確認兌換':'已拒絕',when:r.usedAt||r.useRequestedAt||r.reviewedAt||r.createdAt,kind:'redemption'}});return [...taskRecords,...redemptionRecords].sort((a,b)=>historyTime(b.when)-historyTime(a.when))})
const clock = ref(Date.now())
const historyTime = value => value?.toMillis?.() ?? (value?.seconds ? value.seconds*1000 : 0)
const formatHistoryTime = value => value?.toDate?.().toLocaleString('zh-TW',{timeZone:'Asia/Taipei',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})||''
const title = computed(()=>page.value==='任務'?'任務小天地':page.value==='獎品區'?'我們的獎品區':page.value==='紀錄'?'一路走來的紀錄':page.value==='票根'?'電影票根相簿':page.value==='兌換'?'喜歡的兌換所':page.value==='設定'?'我們的重要日子':'今天也一起加油。')
const todayCycle = () => { const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()); const hour=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',hour:'2-digit',hourCycle:'h23'}).format(new Date())); return date+'-'+(hour>=12?'pm':'am') }
const todayDate = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const yesterdayDate = () => {const date=new Date();date.setDate(date.getDate()-1);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
const taiwanDay = value => value ? new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(historyTime(value))) : ''
const dateParts = value => value.split('-').map(Number)
const dayNumber = value => {const [year,month,day]=dateParts(value);return Date.UTC(year,month-1,day)/86400000}
const nextAnnualDate = (month,day) => {const [currentYear]=dateParts(todayDate()),format=(year)=>`${year}-${String(month).padStart(2,'0')}-${String(month===2&&day===29&&new Date(Date.UTC(year,1,29)).getUTCMonth()!==1?28:day).padStart(2,'0')}`;let date=format(currentYear);if(dayNumber(date)<dayNumber(todayDate()))date=format(currentYear+1);return date}
const dateDistance = value => Math.max(0,dayNumber(value)-dayNumber(todayDate()))
const dateLabel = value => new Date(`${value}T00:00:00+08:00`).toLocaleDateString('zh-TW',{month:'long',day:'numeric',timeZone:'Asia/Taipei'})
const qixiDate = () => {try{const start=dayNumber(todayDate())*86400000,format=new Intl.DateTimeFormat('en-US-u-ca-chinese',{month:'numeric',day:'numeric',timeZone:'Asia/Taipei'});for(let offset=0;offset<=370;offset++){const date=new Date(start+offset*86400000),parts=format.formatToParts(date),month=parts.find(p=>p.type==='month')?.value,day=parts.find(p=>p.type==='day')?.value;if(month==='7'&&day==='7')return `${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}-${String(date.getUTCDate()).padStart(2,'0')}`}return ''}catch{return ''}}
const relationshipDays = computed(()=>{clock.value;if(!coupleDates.value.togetherDate||dayNumber(todayDate())<dayNumber(coupleDates.value.togetherDate))return null;return dayNumber(todayDate())-dayNumber(coupleDates.value.togetherDate)+1})
const holidayDates = computed(()=>{clock.value;const fixed=holidaySeeds.map(e=>({...e,date:nextAnnualDate(e.month,e.day)})),qixi=qixiDate();if(qixi)fixed.push({date:qixi,name:'七夕（農曆七月初七）',emoji:'🌌',about:'牛郎織女相會的傳說，也是華人常說的七夕情人節。'});return fixed.map(e=>({...e,days:dateDistance(e.date)})).sort((a,b)=>a.days-b.days)})
const importantDates = computed(()=>{clock.value;const personal=[];if(coupleDates.value.togetherDate){const [,month,day]=dateParts(coupleDates.value.togetherDate);personal.push({date:nextAnnualDate(month,day),name:'在一起紀念日',emoji:'💗'})}if(coupleDates.value.myBirthday){const [,month,day]=dateParts(coupleDates.value.myBirthday);personal.push({date:nextAnnualDate(month,day),name:'我的生日',emoji:'🎂'})}if(coupleDates.value.partnerBirthday){const [,month,day]=dateParts(coupleDates.value.partnerBirthday);personal.push({date:nextAnnualDate(month,day),name:(partner.value?.name||'另一半')+'的生日',emoji:'🎂'})}return [...holidayDates.value,...personal.map(e=>({...e,days:dateDistance(e.date)}))].sort((a,b)=>a.days-b.days).slice(0,4)})
const expired = t => t.kind==='每日固定' ? t.cycle!==todayCycle() : t.kind==='限期任務' && t.due && todayDate()>t.due
const publishedTaskState = task => task.kind==='每日固定'&&task.rootId===task.id?(tasks.value.find(instance=>instance.rootId===task.id&&instance.cycle===todayCycle())?.status||'open'):task.status
const publishedTaskStatusLabel = task => {const status=publishedTaskState(task);return status==='review'?'對方已完成・待我驗收':status==='done'?'已驗收完成':status==='rejected'?'已駁回・等待對方重做':'等待對方完成'}
const shown = computed(()=>{clock.value;return section.value==='今日任務'?tasks.value.filter(t=>['open','rejected'].includes(t.status)&&t.receiverId===user.value?.uid&&!expired(t)):section.value==='昨日任務'?tasks.value.filter(t=>['open','rejected'].includes(t.status)&&t.receiverId===user.value?.uid&&(t.kind==='每日固定'?String(t.cycle||'').startsWith(yesterdayDate()):taiwanDay(t.createdAt)===yesterdayDate())):section.value==='驗收任務'?tasks.value.filter(t=>t.status==='review'&&t.creatorId===user.value?.uid):tasks.value.filter(t=>t.creatorId===user.value?.uid&&(t.kind==='每日固定'?t.rootId===t.id:!expired(t)))})
const myTaskCount = computed(()=>{clock.value;return tasks.value.filter(t=>['open','rejected'].includes(t.status)&&t.receiverId===user.value?.uid&&!expired(t)).length})
const myPublishedTaskCount = computed(()=>{clock.value;return tasks.value.filter(t=>t.creatorId===user.value?.uid&&(t.kind==='每日固定'?t.rootId===t.id:!expired(t))).length})
const reviewTaskCount = computed(()=>tasks.value.filter(t=>t.status==='review'&&t.creatorId===user.value?.uid).length)
const form=ref({email:'',password:'',nickname:''}), authMode=ref('login'), error=ref(''), taskForm=ref({title:'',note:'',kind:'臨時發布',due:'',rewardType:'fixed',points:5}), invite=ref(''), activeInviteCode=ref(''), rejectReason=ref(''), notice=ref('')
const dateSaveMessage=ref(''), dateSaving=ref(false), dateSaveError=ref(false)
const nicknameDraft=ref(''), nicknameDirty=ref(false), nicknameMessage=ref(''), nicknameSaving=ref(false), nicknameError=ref(false)
const showNicknameEditor=ref(false), showDateEditor=ref(false)
const rewardForm=ref({title:'',points:10,emoji:'🎁'}), editingRewardId=ref('')
const redeemingRewardId=ref('')
const reviewingRedemptionId=ref(''), redemptionReviewError=ref({id:'',message:''})
const editingTaskId=ref(''), editingTaskRootId=ref('')
const stops=[]
let stopTasks=null, stopProfile=null, stopPartner=null, stopPair=null, stopRewards=null, stopRedemptions=null, stopDates=null
let refreshTimer=null
function say(s){notice.value=s;setTimeout(()=>notice.value='',3500)}
async function ensureDailyTasks(){const pairId=profile.value?.pairId;if(!pairId||!user.value)return;const cycle=todayCycle();for(const t of tasks.value){if(t.kind==='每日固定'&&t.rootId===t.id&&t.cycle!==cycle&&!tasks.value.some(x=>x.rootId===t.id&&x.cycle===cycle)){try{const instanceRef=doc(db,'pairs',pairId,'tasks',t.id+'-'+cycle);await setDoc(instanceRef,{title:t.title,note:t.note,kind:t.kind,due:null,cycle,rootId:t.id,rewardType:t.rewardType,points:t.points,status:'open',pairId,creatorId:t.creatorId,receiverId:t.receiverId,createdAt:serverTimestamp()})}catch{}}}}
function syncCoupleDates(){const birthdays=savedCoupleDateData.value.birthdays||{},otherId=otherUserId.value||partner.value?.id;coupleDates.value={togetherDate:savedCoupleDateData.value.togetherDate||'',myBirthday:user.value?birthdays[user.value.uid]||'':'',partnerBirthday:otherId?birthdays[otherId]||'':''}}
function stopLive(){[stopTasks,stopProfile,stopPartner,stopPair,stopRewards,stopRedemptions,stopDates].forEach(fn=>fn?.());stopTasks=stopProfile=stopPartner=stopPair=stopRewards=stopRedemptions=stopDates=null}
watch(()=>{clock.value;return todayCycle()},()=>ensureDailyTasks())
onMounted(()=>{refreshTimer=setInterval(()=>clock.value=Date.now(),30000);stops.push(onAuthStateChanged(auth,async u=>{stopLive();user.value=u;profile.value=null;partner.value=null;otherUserId.value='';savedCoupleDateData.value={};coupleDates.value={togetherDate:'',myBirthday:'',partnerBirthday:''};nicknameDraft.value=u?.displayName||'';nicknameDirty.value=false;nicknameMessage.value='';tasks.value=[];redemptions.value=[];rewards.value=[...starterRewards];if(!u)return
  stopProfile=onSnapshot(doc(db,'users',u.uid),async snap=>{if(!snap.exists()){await setDoc(doc(db,'users',u.uid),{name:u.displayName||u.email,points:0,pointsBalance:0,pairId:null,partnerId:null,createdAt:serverTimestamp()},{merge:true});return}
    profile.value={id:snap.id,...snap.data()};if(!nicknameDirty.value)nicknameDraft.value=profile.value.name||u.displayName||''
    const pairId=profile.value.pairId
    if(pairId){if(!stopTasks)stopTasks=onSnapshot(collection(db,'pairs',pairId,'tasks'),s=>{tasks.value=s.docs.map(d=>({id:d.id,...d.data()}));ensureDailyTasks()})
      if(!stopRewards)stopRewards=onSnapshot(collection(db,'pairs',pairId,'rewards'),async s=>{rewards.value=s.docs.map(d=>({id:d.id,...d.data()}));if(!s.size){const initRef=doc(db,'pairs',pairId,'settings','rewards');await runTransaction(db,async tx=>{const initialized=await tx.get(initRef);if(initialized.exists())return;tx.set(initRef,{initialized:true,createdAt:serverTimestamp()});starterRewards.forEach(r=>tx.set(doc(db,'pairs',pairId,'rewards',r.id),{title:r.title,points:r.points,emoji:r.emoji,createdAt:serverTimestamp()}))})}})
      if(!stopRedemptions)stopRedemptions=onSnapshot(collection(db,'pairs',pairId,'redemptions'),s=>{redemptions.value=s.docs.map(d=>({id:d.id,...d.data()}))})
      if(!stopPair)stopPair=onSnapshot(doc(db,'pairs',pairId),s=>{if(!s.exists())return;const p=s.data(),other=p.ownerId===u.uid?p.partnerId:p.ownerId;otherUserId.value=other||'';syncCoupleDates();if(other&&!stopPartner)stopPartner=onSnapshot(doc(db,'users',other),q=>{partner.value=q.exists()?{id:q.id,...q.data()}:null;syncCoupleDates()})})
      if(!stopDates)stopDates=onSnapshot(doc(db,'pairs',pairId,'settings','dates'),s=>{savedCoupleDateData.value=s.exists()?s.data():{};syncCoupleDates()})}
    else {stopTasks?.();stopRewards?.();stopRedemptions?.();stopPartner?.();stopDates?.();stopTasks=stopRewards=stopRedemptions=stopPartner=stopDates=null;tasks.value=[];redemptions.value=[];rewards.value=[...starterRewards];savedCoupleDateData.value={};coupleDates.value={togetherDate:'',myBirthday:'',partnerBirthday:''}}
  })
}))})
onBeforeUnmount(()=>{clearInterval(refreshTimer);stopLive();stops.forEach(fn=>fn())})
async function authSubmit(){error.value='';try{if(authMode.value==='signup'){const c=await createUserWithEmailAndPassword(auth,form.value.email.trim(),form.value.password);await updateProfile(c.user,{displayName:form.value.nickname.trim()})}else await signInWithEmailAndPassword(auth,form.value.email.trim(),form.value.password);show.value=''}catch(e){error.value=e.code==='auth/email-already-in-use'?'這個 Email 已註冊。':e.code==='auth/invalid-credential'?'Email 或密碼不正確。':e.message}}
async function makeInvite(){if(!profile.value||profile.value.pairId)return say('請先登入，且目前尚未配對。');const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789',bytes=new Uint8Array(5);crypto.getRandomValues(bytes);const code=Array.from(bytes,b=>alphabet[b%alphabet.length]).join('');try{await setDoc(doc(db,'pairs',code),{ownerId:user.value.uid,partnerId:null,createdAt:serverTimestamp(),expiresAt:Timestamp.fromMillis(Date.now()+7*86400000)});await updateDoc(doc(db,'users',user.value.uid),{pairId:code});activeInviteCode.value=code;say('五碼邀請碼已建立，複製後傳給另一半吧。')}catch(e){say('建立失敗：'+e.message)}}
async function cancelInvite(){const code=profile.value?.pairId;if(!user.value||!code)return;try{await runTransaction(db,async tx=>{const pairRef=doc(db,'pairs',code),snapshot=await tx.get(pairRef);if(!snapshot.exists()||snapshot.data().ownerId!==user.value.uid||snapshot.data().partnerId!==null)throw Error('邀請已被使用或不存在，請重新整理狀態。');tx.delete(pairRef);tx.update(doc(db,'users',user.value.uid),{pairId:null})});activeInviteCode.value='';say('已取消原邀請，現在可以輸入另一半的邀請碼。')}catch(e){say(e.code==='permission-denied'?'取消失敗：請發布最新版 Firestore 規則。':'取消邀請失敗：'+e.message)}}
async function copyInvite(code){try{await navigator.clipboard.writeText(code);say('邀請碼已複製。')}catch{say('複製失敗，請手動選取邀請碼。')}}
function openRewardEditor(reward=null){if(!user.value||!profile.value?.pairId)return say('請先登入並邀請另一半配對。');editingRewardId.value=reward?.id||'';rewardForm.value=reward?{title:reward.title,points:reward.points,emoji:reward.emoji}:{title:'',points:10,emoji:'🎁'};show.value='reward'}
async function saveReward(){const pairId=profile.value?.pairId,title=rewardForm.value.title.trim(),points=Number(rewardForm.value.points),emoji=rewardForm.value.emoji.trim()||'🎁';if(!pairId||!user.value)return say('請先登入並完成配對。');if(!title)return say('請輸入禮物名稱。');if(!Number.isInteger(points)||points<0||points>9999)return say('點數請輸入 0 到 9999 的整數。');const data={title,points,emoji,updatedAt:serverTimestamp()};try{if(editingRewardId.value)await updateDoc(doc(db,'pairs',pairId,'rewards',editingRewardId.value),data);else await addDoc(collection(db,'pairs',pairId,'rewards'),{...data,createdAt:serverTimestamp()});show.value='';say(editingRewardId.value?'禮物已更新。':'禮物已新增。')}catch(e){say('儲存禮物失敗：'+e.message)}}
async function removeReward(reward){if(!profile.value?.pairId||!user.value)return say('請先登入並完成配對。');if(!window.confirm(`確定要刪除「${reward.title}」嗎？`))return;try{await deleteDoc(doc(db,'pairs',profile.value.pairId,'rewards',reward.id));say('禮物已刪除。')}catch(e){say('刪除禮物失敗：'+e.message)}}
function openTaskPublisher(){editingTaskId.value='';editingTaskRootId.value='';taskForm.value={title:'',note:'',kind:'臨時發布',due:'',rewardType:'fixed',points:5};show.value='publish'}
function openTaskEditor(task){if(task.status!=='open'||task.creatorId!==user.value?.uid)return say('只有尚未完成的任務可以修改。');editingTaskId.value=task.id;editingTaskRootId.value=task.kind==='每日固定'&&task.rootId===task.id?task.id:'';taskForm.value={title:task.title,note:task.note||'',kind:task.kind,due:task.due||'',rewardType:task.rewardType||'fixed',points:task.points??5};show.value='publish'}
function closeDialog(){show.value='';editingTaskId.value='';editingTaskRootId.value=''}
async function removeTask(task){if(!profile.value?.pairId||!user.value)return say('請先登入並完成配對。');if(task.status!=='open'||task.creatorId!==user.value.uid)return say('只有尚未完成的任務可以刪除。');if(!window.confirm(`確定要刪除「${task.title}」嗎？`))return;try{const related=task.kind==='每日固定'&&task.rootId===task.id?tasks.value.filter(t=>t.id===task.id||(t.rootId===task.id&&t.status==='open')):[task];for(let offset=0;offset<related.length;offset+=400){const batch=writeBatch(db);related.slice(offset,offset+400).forEach(item=>batch.delete(doc(db,'pairs',profile.value.pairId,'tasks',item.id)));await batch.commit()}say('任務已刪除。')}catch(e){say(e.code==='permission-denied'?'刪除失敗：只有發布者能刪除尚未完成的任務。':'刪除任務失敗：'+e.message)}}
async function requestRedemption(reward){
  const pairId=profile.value?.pairId
  if(!pairId||!user.value||!partner.value)return say('請先登入並完成配對。')
  if(redeemingRewardId.value)return
  redeemingRewardId.value=reward.id
  try{
    const rewardRef=doc(db,'pairs',pairId,'rewards',reward.id)
    const redemptionsRef=collection(db,'pairs',pairId,'redemptions')
    const redemptionRef=doc(redemptionsRef)
    const accountRef=doc(db,'users',user.value.uid)
    const [taskList,redemptionList]=await Promise.all([
      getDocs(collection(db,'pairs',pairId,'tasks')),
      getDocs(redemptionsRef)
    ])
    await runTransaction(db,async tx=>{
      const reads=await Promise.all([
        tx.get(rewardRef),tx.get(accountRef),
        ...taskList.docs.map(item=>tx.get(item.ref)),
        ...redemptionList.docs.map(item=>tx.get(item.ref))
      ])
      const giftSnap=reads[0],accountSnap=reads[1]
      const taskSnaps=reads.slice(2,2+taskList.size)
      const redemptionSnaps=reads.slice(2+taskList.size)
      if(!giftSnap.exists())throw Error('這份禮物已被移除，請重新整理。')
      const uid=user.value.uid
      const earned=Number(accountSnap.data()?.pointsBalance||0)+taskSnaps.filter(item=>item.exists()&&item.data().status==='done'&&item.data().receiverId===uid&&!item.data().pointsCredited).reduce((sum,item)=>sum+Number(item.data().roll??item.data().points??0),0)
      const reserved=redemptionSnaps.filter(item=>item.exists()&&item.data().requesterId===uid&&(item.data().status==='pending'||(item.data().status==='approved'&&!item.data().pointsDebited))).reduce((sum,item)=>sum+Number(item.data().points||0),0)
      if(earned-reserved<giftSnap.data().points)throw Error('可用點數不足。')
      tx.set(redemptionRef,{pairId,rewardId:reward.id,title:giftSnap.data().title,emoji:giftSnap.data().emoji,points:giftSnap.data().points,requesterId:uid,approverId:partner.value.id,status:'pending',createdAt:serverTimestamp()})
    })
    say('兌換申請已送出，等待另一半確認。')
  }catch(e){say(e.code==='permission-denied'?'兌換失敗：請確認 Firebase 已發布最新 Firestore 規則。':'兌換失敗：'+e.message)}
  finally{redeemingRewardId.value=''}
}
async function reviewRedemption(redemption,approve){reviewingRedemptionId.value=redemption.id;redemptionReviewError.value={id:'',message:''};try{const redemptionRef=doc(db,'pairs',profile.value.pairId,'redemptions',redemption.id),accountRef=doc(db,'users',redemption.requesterId);await runTransaction(db,async tx=>{const [snapshot,accountSnap]=await Promise.all([tx.get(redemptionRef),tx.get(accountRef)]);if(!snapshot.exists()||snapshot.data().status!=='pending')throw Error('這筆兌換已經處理過，請重新整理。');tx.update(redemptionRef,{status:approve?'approved':'rejected',reviewedAt:serverTimestamp(),...(approve?{pointsDebited:true}:{})});if(approve){const balance=Number(accountSnap.data()?.pointsBalance||0);tx.update(accountRef,{pointsBalance:balance-Number(snapshot.data().points||0),pointsEventRedemptionId:redemption.id})}});say(approve?'已確認兌換，點數已扣除。':'已拒絕兌換，點數已退回。')}catch(e){const message=e.code==='permission-denied'?'Firebase 拒絕了確認交易，請管理者發布最新版 firestore.rules。':'確認失敗：'+e.message;redemptionReviewError.value={id:redemption.id,message};say(message)}finally{reviewingRedemptionId.value=''}}
async function requestPrizeUse(group){const prizeId=group.prizeIds?.[0];if(!prizeId)return;try{await updateDoc(doc(db,'pairs',profile.value.pairId,'redemptions',prizeId),{status:'use_pending',useRequestedAt:serverTimestamp()});say('已申請使用一份「'+group.title+'」，等待另一半確認。')}catch(e){say('申請使用失敗：'+e.message)}}
async function reviewPrizeUse(prize,approve){try{await runTransaction(db,async tx=>{const prizeRef=doc(db,'pairs',profile.value.pairId,'redemptions',prize.id),snapshot=await tx.get(prizeRef);if(!snapshot.exists()||snapshot.data().status!=='use_pending'||snapshot.data().approverId!==user.value?.uid)throw Error('這筆使用申請已處理。');tx.update(prizeRef,approve?{status:'used',usedAt:serverTimestamp()}:{status:'approved',useRejectedAt:serverTimestamp()})});say(approve?'已確認使用，獎品移到已兌換。':'已拒絕使用，獎品回到對方的獎品。')}catch(e){say('處理使用申請失敗：'+e.message)}}
async function saveCoupleDates(){dateSaveMessage.value='';dateSaveError.value=false;const pairId=profile.value?.pairId,otherId=otherUserId.value||partner.value?.id;if(!user.value||!pairId||!otherId){dateSaveError.value=true;dateSaveMessage.value='請先登入並完成配對，再儲存重要日子。';return}dateSaving.value=true;try{await setDoc(doc(db,'pairs',pairId,'settings','dates'),{togetherDate:coupleDates.value.togetherDate||'',birthdays:{[user.value.uid]:coupleDates.value.myBirthday||'', [otherId]:coupleDates.value.partnerBirthday||''},updatedBy:user.value.uid,updatedAt:serverTimestamp()});dateSaveMessage.value='重要日子已儲存，首頁倒數已更新。'}catch(e){dateSaveError.value=true;dateSaveMessage.value=e.code==='permission-denied'?'儲存失敗：請在 Firebase 發布最新版 Firestore 規則。':'儲存重要日子失敗：'+e.message}finally{dateSaving.value=false}}
function markNicknameDirty(){nicknameDirty.value=true;nicknameMessage.value=''}
async function saveNickname(){nicknameMessage.value='';nicknameError.value=false;if(!user.value){nicknameError.value=true;nicknameMessage.value='請先登入再設定暱稱。';return}const nickname=nicknameDraft.value.trim();if(!nickname){nicknameError.value=true;nicknameMessage.value='請輸入暱稱。';return}if(nickname.length>30){nicknameError.value=true;nicknameMessage.value='暱稱請控制在 30 個字以內。';return}nicknameSaving.value=true;try{await updateDoc(doc(db,'users',user.value.uid),{name:nickname});profile.value={...profile.value,name:nickname};nicknameDirty.value=false;try{await updateProfile(user.value,{displayName:nickname});nicknameMessage.value='暱稱已儲存，另一半也會看到更新。'}catch{nicknameError.value=true;nicknameMessage.value='網站暱稱已更新；登入資料同步失敗，請稍後再試。'}}catch(e){nicknameError.value=true;nicknameMessage.value=e.code==='permission-denied'?'儲存失敗：請確認 Firebase 已發布允許更新暱稱的規則。':'儲存暱稱失敗：'+e.message}finally{nicknameSaving.value=false}}
async function joinPair(){const code=invite.value.trim().toUpperCase();if(!user.value)return say('請先登入再輸入邀請碼。');if(!/^[A-Z0-9]{5}$/.test(code))return say('請輸入五碼大寫英文與數字邀請碼。');try{await runTransaction(db,async tx=>{const pairRef=doc(db,'pairs',code),memberRef=doc(db,'users',user.value.uid),[p,member]=await Promise.all([tx.get(pairRef),tx.get(memberRef)]);if(!p.exists()||p.data().partnerId||p.data().ownerId===user.value.uid||!p.data().expiresAt||p.data().expiresAt.toMillis()<=Date.now())throw Error('邀請碼無效、已使用或已過期。');if(member.exists()&&member.data().pairId)throw Error('這個帳號已經有邀請或完成配對，請先取消目前邀請。');tx.update(pairRef,{partnerId:user.value.uid});if(member.exists())tx.update(memberRef,{pairId:code,partnerId:p.data().ownerId});else tx.set(memberRef,{name:user.value.displayName||user.value.email,points:0,pointsBalance:0,pairId:code,partnerId:p.data().ownerId,createdAt:serverTimestamp()})});invite.value='';show.value='';say('配對成功！你們連線了')}catch(e){say(e.code==='permission-denied'?'配對被 Firestore 規則拒絕。請確認已發布最新版 firestore.rules。':e.message)}}
async function publish(){if(!taskForm.value.title.trim())return say('請先輸入任務名稱。');if(taskForm.value.kind==='限期任務'&&!taskForm.value.due)return say('請選擇任務到期日。');const receiverId=otherUserId.value||partner.value?.id||profile.value?.partnerId;if(!profile.value?.pairId||!receiverId)return say('請先登入並邀請另一半配對。');try{const title=taskForm.value.title.trim(),note=taskForm.value.note.trim(),due=taskForm.value.kind==='限期任務'?taskForm.value.due:null,rewardType=taskForm.value.rewardType,points=rewardType==='fixed'?Number(taskForm.value.points):null;if(editingTaskId.value){const task=tasks.value.find(t=>t.id===editingTaskId.value);if(!task||task.creatorId!==user.value.uid||task.status!=='open')throw Error('任務已完成或狀態已改變，請重新整理後再試。');const update={title,note,due,rewardType,points},targets=editingTaskRootId.value?tasks.value.filter(t=>t.id===editingTaskRootId.value||(t.rootId===editingTaskRootId.value&&t.status==='open'&&!expired(t))):[task],batch=writeBatch(db);targets.forEach(t=>batch.update(doc(db,'pairs',profile.value.pairId,'tasks',t.id),update));await batch.commit();say('任務已修改。')}else{const taskRef=doc(collection(db,'pairs',profile.value.pairId,'tasks')),data={title,note,kind:taskForm.value.kind,due,cycle:taskForm.value.kind==='每日固定'?todayCycle():null,rootId:taskForm.value.kind==='每日固定'?taskRef.id:null,rewardType,points,status:'open',pairId:profile.value.pairId,creatorId:user.value.uid,receiverId,createdAt:serverTimestamp()};await setDoc(taskRef,data);section.value='發布任務';say('任務已發布。')}editingTaskId.value='';editingTaskRootId.value='';taskForm.value={title:'',note:'',kind:'臨時發布',due:'',rewardType:'fixed',points:5};show.value=''}catch(e){say(e.code==='permission-denied'?'儲存失敗：請確認 Firebase 已發布允許修改任務的最新版規則。':e.message.startsWith('任務')?e.message:'任務儲存失敗：'+e.message)}}
async function complete(t,allowExpired=false){try{if(t.status==='rejected'){await updateDoc(doc(db,'pairs',profile.value.pairId,'tasks',t.id),{status:'open',rejectReason:'',acknowledgedAt:serverTimestamp()});return}
  if(expired(t)&&!allowExpired)return say('這個任務已經過期。')
  const roll=t.rewardType==='random'?Math.floor(Math.random()*11):Number(t.points||5)
   await updateDoc(doc(db,'pairs',profile.value.pairId,'tasks',t.id),{status:'review',roll,completedAt:serverTimestamp()});t.roll=roll;show.value='dice';setTimeout(()=>show.value='',1800)
}catch(e){say('更新失敗：'+e.message)}}
async function review(t,ok){try{if(ok){const taskRef=doc(db,'pairs',profile.value.pairId,'tasks',t.id),accountRef=doc(db,'users',t.receiverId);await runTransaction(db,async tx=>{const [taskSnap,accountSnap]=await Promise.all([tx.get(taskRef),tx.get(accountRef)]);if(!taskSnap.exists()||taskSnap.data().status!=='review')throw Error('這筆任務已處理過。');const data=taskSnap.data(),roll=Number(data.roll??data.points??0),balance=Number(accountSnap.data()?.pointsBalance||0);tx.update(taskRef,{status:'done',reviewedAt:serverTimestamp(),pointsCredited:true});tx.update(accountRef,{pointsBalance:balance+roll,pointsEventTaskId:t.id})});say('已驗收並送出 '+Number(t.roll??t.points)+' 點。')}else{if(!rejectReason.value.trim())return say('請先填寫駁回原因。');await updateDoc(doc(db,'pairs',profile.value.pairId,'tasks',t.id),{status:'rejected',rejectReason:rejectReason.value.trim(),rejectedAt:serverTimestamp()});rejectReason.value='';say('任務已退回。')}show.value=''}catch(e){say('驗收失敗：'+e.message)}}
</script>

<template>
<div class="app"><div class="random-background" :style="{backgroundImage:'url('+backgroundImage+')'}"></div><header><div class="brand"><img :src="cloudCatImage" alt="" class="cloud-cat-mark"><div><b>貓崽的窩</b><small>our little home</small></div></div><div class="tagline">♥　把喜歡藏進每天的小事裡　♥</div><button v-if="!partner" class="invite mobile-invite" @click="show='pair'">💌 邀請另一半</button><button class="login" @click="user?signOut(auth):show='login'">{{user?'登出 '+name:'登入 / 註冊'}}</button></header>
<main><aside class="side"><div class="couple"><span class="face">{{name.slice(0,1)}}</span><span class="face pink">♡</span><div><b>{{profile?.pairId?name+' & '+(partner?.name||'另一半'):'我們的小宇宙'}}</b><small>{{profile?.pairId?'兩顆心，住在同一個小窩裡':'登入後邀請另一半加入'}}</small></div></div><div class="caption">OUR LITTLE SPACE</div><button v-for="([icon,t]) in tabs" :key="t" :class="{selected:page===t}" @click="page=t"><img class="navicon-img" :src="icon" :alt="t"><span><b>{{t}}</b><i v-if="t==='任務'&&hasTaskAttention||t==='獎品'&&hasPrizeAttention" class="attention-dot" aria-label="有待處理項目"></i><small>{{t==='任務'?'一起完成小事':t==='獎品'?'收藏喜歡的禮物':t==='兌換'?'讓點數變成驚喜':t==='票根'?'收藏電影回憶':t==='紀錄'?'一路走來的回憶':t==='設定'?'生日和紀念日倒數':'我們的日常'}}</small></span></button><div class="quote">you are my<br>favorite person. <small>— every little day</small></div></aside>
<section class="content"><div class="eyebrow">✦　OUR LITTLE SPACE</div><h1>{{title}} <img :src="cloudCatImage" alt="" class="cloud-cat-inline"></h1><p class="sub">每一個小小任務，都是偷偷說喜歡的方式。</p>
<template v-if="page==='首頁'"><div class="hero"><div><small>✦ OUR LITTLE ROUTINE ✦</small><h2>喜歡，不只說說而已。<br><em>我們把它做成日常。</em></h2><p>一杯記得的飲料、一句晚安，還有好多為彼此用心的小事。</p><button class="primary" @click="page='任務';openTaskPublisher()">發布一個小任務　＋</button></div><div class="pup center-pup"><img class="center-pup-icon" :src="homepageIcon" alt="首頁角色圖"><img :src="cloudCatImage" alt="" class="cloud-cat-bubble"></div></div><div class="metrics"><button @click="page='任務';section='今日任務'"><small>我的任務</small><b>{{myTaskCount}} 件</b><i>查看收到的任務　›</i></button><button @click="page='任務';section='發布任務'"><small>我發布的任務</small><b>{{myPublishedTaskCount}} 件</b><i>管理發布內容　›</i></button><button @click="page='任務';section='驗收任務'"><small>等待驗收</small><b>{{reviewTaskCount}} 件</b><i>確認對方完成的任務　›</i></button><button @click="page='獎品';prizeSection='獎品'"><small>我的專屬點數</small><b>{{points}} pt</b><i>對方有 {{partnerPoints}} 點　›</i></button></div><section class="important-days"><div class="days-header"><div><small>OUR LITTLE CALENDAR</small><h2>接下來的重要日子</h2></div><button @click="page='設定'">設定日期　›</button></div><div v-if="relationshipDays!==null" class="together-counter">我們已經一起 <strong>{{relationshipDays}}</strong> 天<span v-if="importantDates.some(d=>d.name==='在一起紀念日')">・下個週年還有 {{importantDates.find(d=>d.name==='在一起紀念日')?.days}} 天</span></div><div class="important-date-list"><article v-for="d in importantDates" :key="d.name" class="important-date-item"><span>{{d.emoji}}</span><b>{{d.name}}</b><small>{{dateLabel(d.date)}}・{{d.days===0?'就是今天':`還有 ${d.days} 天`}}</small></article></div></section><div class="note">「最喜歡的日常，是每一件事都有你。」 <small>一張貓咪捎來的小紙條　♡</small></div></template>
<template v-else-if="page==='任務'"><div class="bar"><div class="seg"><button v-for="s in ['今日任務','昨日任務','發布任務','驗收任務']" :key="s" :class="{on:section===s}" @click="section=s">{{s}}</button></div><button class="primary" @click="openTaskPublisher">＋ 發布新任務</button></div><p v-if="user&&!profile?.pairId" class="empty">先邀請另一半加入你們的小宇宙。</p><article v-for="(t,i) in shown" :key="t.id" :class="['task',t.kind==='臨時發布'?'task-temporary':t.kind==='每日固定'?'task-daily':'task-deadline']"><div class="number">{{String(i+1).padStart(2,'0')}}<hr>♡</div><div class="tasktext"><small class="task-kind" :class="{'task-kind-temporary':t.kind==='臨時發布','task-kind-daily':t.kind==='每日固定','task-kind-deadline':t.kind==='限期任務'}">{{t.kind}}</small><span class="task-kind-note">　·　小小的心意</span><h3>{{t.title}} <i v-if="taskNeedsAttention(t)" class="attention-dot" aria-label="需要你處理"></i></h3><small v-if="section==='發布任務'" class="published-task-status" :class="'status-'+publishedTaskState(t)">{{publishedTaskStatusLabel(t)}}</small><p>{{t.note||'一件小小的心意，等你完成。'}}</p><div v-if="section==='發布任務'&&t.creatorId===user?.uid&&t.status==='open'" class="task-actions"><button class="task-edit" @click="openTaskEditor(t)">修改</button><button class="task-delete" @click="removeTask(t)">刪除</button></div></div><div class="reward"><b>{{t.roll??t.points}}</b><small>POINTS</small></div><button v-if="t.status==='review'&&t.creatorId===user?.uid" class="complete" @click="show='review'">驗收任務</button><button v-else-if="t.receiverId===user?.uid" class="complete" @click="complete(t,section==='昨日任務')">{{t.status==='rejected'?'我知道了':'✓ 我完成了'}}</button></article><div v-if="!shown.length" class="empty"><img :src="cloudCatImage" alt="" class="cloud-cat-empty"><h3>這裡還空空的呢</h3><p>配對後發布小任務，讓今天多一件期待。</p></div></template>
<template v-else-if="page==='獎品'">
  <div class="bar"><div class="seg"><button v-for="tab in ['獎品','對方的獎品','待確認','已兌換']" :key="tab" :class="{on:prizeSection===tab}" @click="prizeSection=tab">{{tab}}<i v-if="tab==='待確認'&&hasPrizeAttention" class="attention-dot" aria-label="有待確認獎品"></i></button></div></div>
  <template v-if="prizeSection==='獎品'"><div class="points"><small>MY PRIZES</small><b>{{myPrizes.reduce((sum,item)=>sum+item.quantity,0)}}<i> 件獎品</i></b><p>另一半已確認，隨時可以申請使用。</p></div><section class="redemption-panel"><h3>我的獎品</h3><article v-for="r in myPrizes" :key="r.title" class="redemption-item"><span class="redemption-emoji">{{r.emoji}}</span><div class="redemption-info"><b>{{r.title}} <span class="prize-quantity">× {{r.quantity}}</span></b><small>持有 {{r.quantity}} 份</small></div><button @click="requestPrizeUse(r)">申請使用 1 份</button></article><p v-if="!myPrizes.length" class="empty">還沒有獎品，去兌換一份喜歡的禮物吧。</p></section></template>
  <template v-else-if="prizeSection==='對方的獎品'"><div class="points"><small>PARTNER'S PRIZES</small><b>{{partnerPrizes.reduce((sum,item)=>sum+item.quantity,0)}}<i> 件獎品</i></b><p>只能查看另一半目前持有的獎品。</p></div><section class="redemption-panel"><h3>{{partner?.name||'另一半'}}的獎品</h3><article v-for="r in partnerPrizes" :key="r.title" class="redemption-item"><span class="redemption-emoji">{{r.emoji}}</span><div class="redemption-info"><b>{{r.title}} <span class="prize-quantity">× {{r.quantity}}</span></b><small>持有 {{r.quantity}} 份</small></div></article><p v-if="!partnerPrizes.length" class="empty">另一半目前還沒有獎品。</p></section></template>
  <template v-else-if="prizeSection==='待確認'"><section class="redemption-panel"><h3>等待我確認</h3><article v-for="r in prizesToReview" :key="r.id" class="redemption-item"><span class="redemption-emoji">{{r.emoji}}</span><div class="redemption-info"><b>{{r.title}}</b><small :class="r.status==='pending'?'pending-redeem':'pending-use'">{{r.status==='pending'?'兌換申請・確認後扣 '+r.points+' 點':'使用申請・確認後移到已兌換'}}</small></div><button :disabled="!!reviewingRedemptionId" @click="r.status==='pending'?reviewRedemption(r,true):reviewPrizeUse(r,true)">{{reviewingRedemptionId===r.id?'處理中…':'確認'}}</button><button class="redeem-reject" :disabled="!!reviewingRedemptionId" @click="r.status==='pending'?reviewRedemption(r,false):reviewPrizeUse(r,false)">拒絕</button><small v-if="redemptionReviewError.id===r.id" class="redemption-error" role="alert">{{redemptionReviewError.message}}</small></article><p v-if="!prizesToReview.length" class="empty">目前沒有需要你確認的獎品。</p></section><section class="redemption-panel"><h3>等待對方確認</h3><article v-for="r in pendingPrizes.filter(item=>item.requesterId===user?.uid)" :key="r.id" class="redemption-item"><span class="redemption-emoji">{{r.emoji}}</span><div class="redemption-info"><b>{{r.title}}</b><small :class="r.status==='pending'?'pending-redeem':'pending-use'">{{r.status==='pending'?'兌換申請・等待對方確認':'使用申請・等待對方確認'}}</small></div></article><p v-if="!pendingPrizes.some(r=>r.requesterId===user?.uid)" class="empty">沒有等待對方確認的申請。</p></section></template>
  <section v-else class="redemption-panel"><h3>已兌換</h3><article v-for="r in usedPrizes" :key="r.id" class="redemption-item"><span class="redemption-emoji">{{r.emoji}}</span><div class="redemption-info"><b>{{r.title}}</b><small>已確認使用・{{formatHistoryTime(r.usedAt)}}</small></div></article><p v-if="!usedPrizes.length" class="empty">目前沒有已兌換獎品。</p></section>
</template>
<template v-else-if="page==='紀錄'"><div class="history-list"><article v-for="record in historyRecords" :key="record.id" class="history-record"><span>{{record.icon}}</span><div><b>{{record.title}}</b><span class="history-status" :data-status="record.status">{{record.statusLabel}}</span><small>{{record.detail}}</small><time v-if="record.when">{{formatHistoryTime(record.when)}}</time></div><strong>{{record.amount}}</strong></article><div v-if="!historyRecords.length" class="empty"><h3>還沒有活動紀錄</h3><p>完成任務或兌換禮物後，紀錄會顯示在這裡。</p></div></div></template><template v-else-if="page==='兌換'"><div class="bar reward-bar"><div><small>OUR LITTLE TREATS</small><h2>把喜歡換成小驚喜</h2></div><button class="primary" @click="openRewardEditor()">＋ 新增禮物</button></div><div class="redeem-balance"><div><small>我的可用點數</small><strong>{{points}} <span>點</span></strong></div><p><span v-if="reservedPoints">待確認保留 {{reservedPoints}} 點<br></span>另一半確認兌換後才正式扣點。</p></div><div class="rewards"><article v-for="r in rewards" :key="r.id"><div class="rewardart">{{r.emoji}}</div><h3>{{r.title}}</h3><small>✦ {{r.points}} 點</small><div class="reward-actions"><button class="redeem-button" :disabled="!user||!profile?.pairId||points<r.points||!!redeemingRewardId" @click="requestRedemption(r)">{{redeemingRewardId===r.id?'送出中…':points<r.points?'點數不足':'兌換'}}</button><button class="reward-edit" @click="openRewardEditor(r)">修改</button><button class="reward-delete" @click="removeReward(r)">刪除</button></div></article></div><div v-if="!rewards.length" class="empty">🎁<h3>還沒有禮物</h3><p>新增一份小驚喜，讓點數有期待。</p></div></template><template v-else-if="page==='票根'"><TicketAlbum :pair-id="profile?.pairId||''" :user-id="user?.uid||''" :partner-name="partner?.name||'另一半'" /></template><template v-else><section class="nickname-settings"><div class="settings-heading"><div><h2>個人暱稱</h2><p>目前暱稱：{{name}}</p></div><button class="settings-toggle" type="button" :aria-expanded="showNicknameEditor" @click="showNicknameEditor=!showNicknameEditor">{{showNicknameEditor?'收起':'修改暱稱'}}</button></div><p v-if="showNicknameEditor">修改後會同步更新你們空間裡顯示的名稱。</p><form v-if="showNicknameEditor" class="nickname-form" @submit.prevent="saveNickname"><label>你的暱稱<input v-model="nicknameDraft" @input="markNicknameDirty" maxlength="30" placeholder="輸入暱稱" :disabled="!user" required></label><button class="primary" type="submit" :disabled="!user||nicknameSaving">儲存暱稱</button><p v-if="nicknameMessage" class="nickname-message" :class="{error:nicknameError}">{{nicknameMessage}}</p><p v-else-if="!user" class="form-hint">請先登入後設定暱稱。</p></form></section><section class="date-settings"><div class="settings-heading"><div><h2>重要日期</h2><p>在一起的日子、生日與節日提醒</p></div><button class="settings-toggle" type="button" :aria-expanded="showDateEditor" @click="showDateEditor=!showDateEditor">{{showDateEditor?'收起':'修改重要日期'}}</button></div><p v-if="showDateEditor">設定後，首頁會計算在一起的天數，並提醒你們生日和接下來的節日。</p><form v-if="showDateEditor" class="date-form" @submit.prevent="saveCoupleDates"><label>在一起的日子<input v-model="coupleDates.togetherDate" type="date"></label><label>{{name}}的生日<input v-model="coupleDates.myBirthday" type="date"></label><label>{{partner?.name||'另一半'}}的生日<input v-model="coupleDates.partnerBirthday" type="date"></label><button class="primary wide" type="submit" :disabled="dateSaving||!user||!profile?.pairId||!otherUserId">{{dateSaving?'儲存中…':'儲存重要日子'}}</button><p v-if="dateSaveMessage" class="date-save-message" :class="{error:dateSaveError}">{{dateSaveMessage}}</p><p v-if="!user" class="form-hint">請登入並完成配對後儲存你們的重要日子。</p><p v-else-if="!profile?.pairId||!otherUserId" class="form-hint">先邀請另一半加入並完成配對，設定才會同步保存。</p></form><section v-if="showDateEditor" class="holiday-list"><h2>常見節日</h2><article v-for="d in holidayDates" :key="d.name" class="holiday-item"><span>{{d.emoji}}</span><div><b>{{d.name}}</b><p>{{d.about}}</p></div><strong>{{d.days===0?'今天':`${d.days} 天後`}}<small>{{dateLabel(d.date)}}</small></strong></article></section></section></template>
</section><aside class="right"><small>OUR LITTLE JOURNAL</small><div class="calendar">OUR DAY<strong>{{new Date().toLocaleDateString('zh-TW',{day:'2-digit',timeZone:'Asia/Taipei'})}}</strong>{{new Date().toLocaleDateString('zh-TW',{weekday:'long',timeZone:'Asia/Taipei'})}}</div><div class="thought">TODAY'S LITTLE THOUGHT<p>有你一起，<br>普通的日子<br>也亮亮的。</p>— from kitty <img :src="cloudCatImage" alt="" class="cloud-cat-thought"></div><div class="pup sidepup"><img class="side-pup-icon" :src="sidebarIcon" alt="側邊角色圖"></div><button v-if="!partner" class="invite" @click="show='pair'">💌　邀請另一半</button></aside></main>
<nav class="mobile-nav" :class="{paired:!!partner}"><button v-for="([icon,t]) in tabs" :key="t" :class="{selected:page===t}" @click="page=t"><img class="mobile-icon" :src="icon" :alt="t">{{t}}<i v-if="t==='任務'&&hasTaskAttention||t==='獎品'&&hasPrizeAttention" class="attention-dot" aria-label="有待處理項目"></i></button><button v-if="!partner" class="mobile-invite-nav" title="邀請另一半" @click="show='pair'"><span>💌</span>邀請</button></nav>
<div v-if="notice" class="toast-pop">{{notice}}</div><div v-if="show" class="overlay" @pointerdown.self="show=''"><section class="dialog"><button class="close" @click="show=''">×</button><div class="dialog-icon"><img v-if="show==='login'" :src="cloudCatImage" alt="" class="cloud-cat-dialog"><span v-else>{{show==='dice'?'🎲':show==='pair'?'💌':show==='review'?'✨':show==='reward'?'🎁':'📝'}}</span></div><small>YOUR LITTLE HOME</small><h2>{{show==='login'?'回到你們的小宇宙':show==='pair'?'邀請另一半一起來':show==='review'?'任務完成驗收':show==='dice'?'任務完成！':show==='reward'?(editingRewardId?'修改禮物':'新增禮物'):show==='publish'?(editingTaskId?'修改任務':'發布一個小任務'):'發布一個小任務'}}</h2>
<template v-if="show==='login'"><form @submit.prevent="authSubmit"><input v-if="authMode==='signup'" v-model="form.nickname" placeholder="暱稱" required><input v-model="form.email" type="email" placeholder="Email" autocomplete="email" required><input v-model="form.password" type="password" placeholder="密碼（至少 6 個字元）" minlength="6" required><p v-if="error" class="auth-error">{{error}}</p><button class="primary wide" :disabled="authBusy">{{authBusy?'請稍候…':authMode==='signup'?'建立帳號':'登入'}}</button></form><button class="auth-switch login-switch" @click="authMode=authMode==='login'?'signup':'login'">{{authMode==='login'?'還沒有帳號？註冊':'已有帳號？返回登入'}}</button></template>
<template v-else-if="show==='pair'"><p>邀請碼為五碼大寫英文與數字，建立後 7 天有效，配對後立即失效。</p><div v-if="user&&profile?.pairId&&!partner" class="invite-code-box"><strong>{{activeInviteCode||profile.pairId}}</strong><button class="copy-invite" @click="copyInvite(activeInviteCode||profile.pairId)">複製</button></div><button v-if="user&&profile?.pairId&&!partner" class="auth-switch" @click="cancelInvite">取消目前邀請，改輸入另一半的邀請碼</button><button v-if="user&&!profile?.pairId" class="primary wide" @click="makeInvite">建立五碼邀請碼</button><input v-if="user&&!profile?.pairId" v-model="invite" maxlength="5" placeholder="輸入另一半的五碼邀請碼"><button v-if="user&&!profile?.pairId" class="primary wide" @click="joinPair">使用邀請碼配對</button><p v-if="!user">請先登入。</p><p v-if="partner">你們已經配對成功</p></template>
<template v-else-if="show==='reward'"><form @submit.prevent="saveReward"><label>禮物名稱<input v-model="rewardForm.title" maxlength="60" placeholder="例如：一起看電影" required></label><label>所需點數<input v-model.number="rewardForm.points" type="number" min="0" max="9999" step="1" required></label><label>禮物圖示<input v-model="rewardForm.emoji" maxlength="8" placeholder="🎁"></label><button class="primary wide" type="submit">{{editingRewardId?'儲存修改':'新增禮物'}}</button></form></template>
<template v-else-if="show==='publish'"><form @submit.prevent="publish"><label>任務名稱<input v-model="taskForm.title" maxlength="80" placeholder="例如：幫我買草莓牛奶" required></label><label>給對方的小紙條<textarea v-model="taskForm.note" maxlength="200" placeholder="補充小細節或偷偷撒個嬌…"></textarea></label><label>發布方式<select v-model="taskForm.kind" :disabled="!!editingTaskId"><option value="臨時發布">臨時發布</option><option value="每日固定">每天固定（台灣時間 12:00 刷新）</option><option value="限期任務">有期限，到期日隔日 00:00 過期</option></select></label><label v-if="taskForm.kind==='限期任務'">到期日<input v-model="taskForm.due" type="date" :min="todayDate()" required></label><div class="award-options"><span>完成獎勵</span><label><input v-model="taskForm.rewardType" type="radio" value="fixed"> 固定點數</label><label><input v-model="taskForm.rewardType" type="radio" value="random"> 完成時抽 0–10 點 🎲</label></div><label v-if="taskForm.rewardType==='fixed'">獎勵點數<input v-model.number="taskForm.points" type="number" min="0" max="999" required></label><p v-else class="form-hint">接收方按下「我完成了」時會擲骰子，驗收後才收到點數。</p><button class="primary wide" type="submit">{{editingTaskId?'儲存修改':'發布給另一半'}}</button></form></template>
<template v-else-if="show==='review'"><p>任務「{{tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid)?.title}}」已完成。確認後點數會送給對方。</p><button class="primary wide" @click="tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid)&&review(tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid),true)">✓ 驗收並送出點數</button><textarea v-model="rejectReason" placeholder="駁回原因（對方會看到）"></textarea><button class="auth-switch" @click="tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid)&&review(tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid),false)">駁回並退回任務</button></template>
<template v-else><div class="die">🎲 <b>{{tasks.find(t=>t.status==='review'&&t.receiverId===user?.uid)?.roll??'✦'}}</b> pt</div><p>已送出驗收，等待發布者確認。</p></template></section></div>
</div>
</template>
